pub type Point = [f64; 2];
pub type Ring = Vec<Point>;
pub type Polygon = Vec<Ring>;

pub fn build_polygon(n: i32) -> Polygon {
    let mut polygon = Vec::new();

    for i in 0..n {
        let offset = f64::from(i * 2);
        let side = f64::from(n);
        let ring = vec![
            [offset, offset],
            [offset + side, offset],
            [offset + side, offset + side],
            [offset, offset + side],
        ];
        polygon.push(ring);
    }

    polygon
}

